import{m as a}from"./index-Dw4R-IFa.js";const r={async getAllPayments(){return(await a.get("/payments")).data},async createPayment(e){return(await a.post("/payments",e)).data},async approvePayment(e,s=!1){return(await a.put(`/payments/${e}/approve`,{isInstallment:s})).data},async deletePayment(e){return(await a.delete(`/payments/${e}`)).data},async getUserPayments(e){return(await a.get(`/payments/user/${e}`)).data},async confirmPayment(e,s=!1){return(await a.put(`/payments/${e}/confirm`,{isInstallment:s})).data}};export{r as P};
